package com.finanscore.notification.infrastructure;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="notification")public class NotificationEntity{@Id public UUID id;@Column(name="request_id",nullable=false)public UUID requestId;@Column(name="user_id",nullable=false)public Long userId;@Column(name="report_id",nullable=false)public UUID reportId;@Column(name="recipient_email",nullable=false)public String recipientEmail;@Column(nullable=false)public String status;@Column(name="created_at",nullable=false)public Instant createdAt;}